{"code":"import csv, json
from pathlib import Path

nodes=[]
with open('input/nodes.csv', newline='', encoding='utf-8') as f:
    reader=csv.DictReader(f)
    for row in reader:
        nodes.append({
            'id': row['id'],
            'text': row['text'],
            'speaker': row['speaker'],
            'type': row['type'],
        })

edges=[]
with open('input/edges.csv', newline='', encoding='utf-8') as f:
    reader=csv.DictReader(f)
    for row in reader:
        edges.append({
            'from': row['source'],
            'to': row['target'],
            'text': row['text'],
        })

out={'nodes': nodes, 'edges': edges}
Path('output').mkdir(exist_ok=True)
with open('output/graph.json','w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=2)
print('written')"}
